import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"System map: the four components and how they cooperate","description":"","frontmatter":{},"headers":[],"relativePath":"arch/system-map.md","filePath":"arch/system-map.md"}'),t={name:"arch/system-map.md"};function i(r,e,l,c,d,p){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="system-map-the-four-components-and-how-they-cooperate" tabindex="-1">System map: the four components and how they cooperate <a class="header-anchor" href="#system-map-the-four-components-and-how-they-cooperate" aria-label="Permalink to &quot;System map: the four components and how they cooperate&quot;">​</a></h1><p>Open Cube OS is not one program. Four independently linked binaries share one repository and one version string, and pass control between each other through fixed physical memory contracts. This page is the panoramic view: what each component is, the collaboration diagram, the version chain, the physical memory map that binds them, and every boot mode the system supports. Deep dives: <a href="./boot-flow.html">boot-flow.md</a> for the loader chain, <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a> for the cross-component conspiracies, <a href="./tree-map.html">tree-map.md</a> for the file tree.</p><h2 id="the-four-components" tabindex="-1">The four components <a class="header-anchor" href="#the-four-components" aria-label="Permalink to &quot;The four components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Location</th><th>Identity</th></tr></thead><tbody><tr><td><strong>OCBL</strong></td><td><code>ocbl/</code></td><td>The boot loader (BIOS + UEFI flavors). Replaced GRUB on the release ISO in 3.0.0-WP05 B5-7. Scans every disk, classifies every bootable volume, runs the 10-second menu, hands the chosen kernel a GRUB-identical multiboot2 state.</td></tr><tr><td><strong>OCSE</strong></td><td><code>ocse/</code></td><td>&quot;OpenCubeOS Setup Environment&quot; - the installer. A small standalone kernel <strong>vendored from git tag v1.0.0</strong> (143 files, frozen on purpose: see <code>ocse/VENDORING.md</code>), carrying its own driver set (ATA/AHCI/NVMe/virtio/USB/ACPI), a 40-command shell (OCSECL), a 9-step GUI wizard and an 8-step install state machine.</td></tr><tr><td><strong>OCOS</strong></td><td><code>ocos/</code></td><td>The main system: the L0 service kernel (<code>ocos/kernel/</code>), the driver layer (<code>ocos/drivers/</code>), the 24 service families (<code>ocos/services/</code>), the ring-3 API contract (<code>ocos/interface/</code>) and 284 embedded ring-3 applications (<code>ocos/l1apps/</code>). Everything a running system is.</td></tr><tr><td><strong>OCIRE</strong></td><td><code>ocire/</code></td><td>The independent recovery kernel. An L0 <em>peer</em> of OCOS - own include paths, own linker script, no OCOS headers (the WP-01 independence rule). Own ATA driver, own FAT12/32 code, own SHA-256, own console, own IDT, own ACPI, own 6300ESB watchdog. Boots as supervisor (<code>ocire.mode=sup</code>) or full recovery shell, kexecs OCOS, and repairs the machine when OCOS cannot boot.</td></tr></tbody></table><p>Only three things are shared source-side: <code>include/ocbl_state.h</code> (the byte-exact boot-state contract used by all of OCBL, OCOS, OCIRE), the Chinese font data (OCIRE&#39;s <code>ocire/generated/ocire_cn_font_data.c</code> is generated from <code>ocse/chinese/chinese_font_data.c</code>), and the L1 ABI that the OCIRE log agent compiles against (an ABI, not an include).</p><h2 id="collaboration-diagram" tabindex="-1">Collaboration diagram <a class="header-anchor" href="#collaboration-diagram" aria-label="Permalink to &quot;Collaboration diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> power-on</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span> +--------------------------------------------------------------+</span></span>
<span class="line"><span> | OCBL  (BIOS stage1 @0x7C00 -&gt; core @0x7E00  /  UEFI PE app)  |</span></span>
<span class="line"><span> |  * 6-class volume scanner: OCSE OCOS OCIRE WINDOWS LINUX     |</span></span>
<span class="line"><span> |    GENERIC  (+ synthesized Shutdown row)                     |</span></span>
<span class="line"><span> |  * 3-key 10 s menu (Up/Down/Enter only), serial-mirrored     |</span></span>
<span class="line"><span> |  * A/B slot judgment on the first OCOS volume (flag files)   |</span></span>
<span class="line"><span> |  * boot-state monitor: reads 0x98000/0x9B000, arms 6300ESB   |</span></span>
<span class="line"><span> |  * auto-route: pending BOOT_FAILED record -&gt; OCIRE one-shot  |</span></span>
<span class="line"><span> +----+----------------+----------------+----------------+------+</span></span>
<span class="line"><span>      |                |                |                |</span></span>
<span class="line"><span>   OCOS             OCIRE             OCSE          foreign VBR/ESP</span></span>
<span class="line"><span>      |                |                |                |</span></span>
<span class="line"><span>      v                v                v                v</span></span>
<span class="line"><span> mb2 handoff      mb2 handoff      mb2 handoff      chainload</span></span>
<span class="line"><span> EAX=0x36D76289   EAX=0x36D76289   EAX=0x36D76289   (0x7C00 jump /</span></span>
<span class="line"><span> EBX=MBI@0x50000  EBX=MBI@0x50000  EBX=MBI@0x50000   LoadImage)</span></span>
<span class="line"><span> 32-bit, pg off    32-bit, pg off   32-bit, pg off</span></span>
<span class="line"><span>      |                |                |</span></span>
<span class="line"><span>      |         OCIRE kexec           +--&gt; installs OCOS disks:</span></span>
<span class="line"><span>      |         OCOS ELF -&gt; [1MiB,8MiB)     ocbl-install writes the</span></span>
<span class="line"><span>      |         MBI rebuilt @0x80000        OCBL MBR flavor, mkfs.fat32,</span></span>
<span class="line"><span>      |         agent module appended       tar payload, boot flags</span></span>
<span class="line"><span>      |                |</span></span>
<span class="line"><span>      v                v</span></span>
<span class="line"><span> +-------------+  +--------------------+</span></span>
<span class="line"><span> | OCOS kmain  |  | OCIRE supervisor   |</span></span>
<span class="line"><span> | boot chain  |  | mailbox WAIT_SIGNAL|</span></span>
<span class="line"><span> | 1/4 kernel  |  | arm wdt 60 s       |</span></span>
<span class="line"><span> | 2/4 drivers |  | kexec OCOS -------&gt;|  (OCOS boots with</span></span>
<span class="line"><span> | 3/4 service |  +--------------------+   oc.* embed facts)</span></span>
<span class="line"><span> | 4/4 iface   |</span></span>
<span class="line"><span> | L1 ush      |  OCOS first seconds:</span></span>
<span class="line"><span> |  ...        |   ocembed_boot_confirm(): mailbox SIGNAL_OK,</span></span>
<span class="line"><span> +-------------+   disarm i6300esb, spawn ocire_guard agent,</span></span>
<span class="line"><span>                   write-protect the whole recovery disk.</span></span></code></pre></div><p>The reverse edges matter as much as the forward ones: when OCOS dies during boot, the 6300ESB watchdog resets the machine, OCBL reads the 0x9B000 post-mortem record, judges the failure from the 0x98000 stage island, and routes the next boot into OCIRE without any menu interaction (the full chain is <a href="./crash-recovery.html">crash-recovery.md</a>).</p><h2 id="the-version-chain" tabindex="-1">The version chain <a class="header-anchor" href="#the-version-chain" aria-label="Permalink to &quot;The version chain&quot;">​</a></h2><p>One <code>OC_RELEASE_VERSION</code> and one <code>OC_KERNEL_BUILD</code> flow into all four banners - the four components are released in lockstep by construction (<code>Makefile</code> lines 90/103-104):</p><div class="language-make vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">make</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_RELEASE_VERSION ?= 3.0.0-NAK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_KERNEL_BUILD_OFFSET := 21</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_KERNEL_BUILD ?= </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expr </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(git rev-list --count HEAD ...) + 21)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Component</th><th>Version stamp source</th><th>Notes</th></tr></thead><tbody><tr><td>OCOS</td><td><code>-D OC_RELEASE_VERSION/-D OC_KERNEL_BUILD</code> + <code>ocos/kernel/generated/version_gen.h</code> (<code>OC_VERSION_STAMP</code>, cmp-guarded so a version bump forces recompilation - the <code>-D</code> flags are invisible to <code>-MMD</code> dependency tracking, a live-caught stale-banner bug)</td><td>Banner: <code>Open Cube OS [3.0.0-...]</code></td></tr><tr><td>OCBL</td><td><code>-DOCBL_RELEASE=\\&quot;$(OC_RELEASE_VERSION)\\&quot;</code> + <code>-DOCBL_BUILD=$(OC_KERNEL_BUILD)</code> (<code>ocbl/ocbl.mk</code>)</td><td>Fallback literals <code>3.0.0-WP05</code>/<code>0</code> in sources; no independent version</td></tr><tr><td>OCIRE</td><td><code>OCIRE_VERSION ?= $(OC_RELEASE_VERSION)</code> + <code>ocire/generated/ocire_version_gen.h</code> (<code>OCIRE_STAMP</code>)</td><td>BUG #92 fix - it used to carry its own literal four milestones behind</td></tr><tr><td>OCSE</td><td><code>-DOCSE_RELEASE=\\&quot;$(OC_RELEASE_VERSION)-ocse\\&quot;</code> + <code>OCSE_BUILD=$(OC_KERNEL_BUILD)</code></td><td>The <strong>only</strong> component with a distinct suffix (<code>-ocse</code>), because it is a vendored v1.0.0 kernel wearing the current release number</td></tr></tbody></table><p>The <code>+21</code> offset keeps the public build sequence monotonic above the already-published build 274. Per-component WP tags (WP-05, WP-07a, ...) exist only in file-header comments, never in shipped banners.</p><h2 id="the-physical-memory-contract" tabindex="-1">The physical memory contract <a class="header-anchor" href="#the-physical-memory-contract" aria-label="Permalink to &quot;The physical memory contract&quot;">​</a></h2><p>The four components never share code, but they share physical addresses. These are load-bearing constants (defined in <code>ocbl/common/ocbl_boot.h</code>, <code>ocbl/common/ocbl_types.h</code>, <code>include/ocbl_state.h</code>, the three linker scripts):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   0x00500-0x0051F   OCBL A20 test area</span></span>
<span class="line"><span>   0x00520           stage1 facts: {boot drive, flavor, entry CS}</span></span>
<span class="line"><span>   0x007C00          OCBL stage1 (512 B, both flavors)</span></span>
<span class="line"><span>   0x007E00..        OCBL core (linker_bios.ld; entry core_head)</span></span>
<span class="line"><span>   0x30000           64 KiB read bounce window; EFI: 64-&gt;32 handoff blob</span></span>
<span class="line"><span>   0x40000-0x4FFFF   real-mode trampoline + VBE/geom scratch</span></span>
<span class="line"><span>                     (fallback PT block when the EBDA overlaps 0x8F000+)</span></span>
<span class="line"><span>   0x50000           multiboot2 info build buffer (OCBL_MBI_BASE;</span></span>
<span class="line"><span>                     OCIRE kexec rebuilds its MBI at 0x80000 instead)</span></span>
<span class="line"><span>   0x60000-0x61FFF   E820 / GetMemoryMap buffer</span></span>
<span class="line"><span>   0x62000 / 0x62800 OCBL fs sector window / 128 KiB FAT cache</span></span>
<span class="line"><span>   0x82800-0x8DFFF   OCBL core stack (top 0x8E000 - WP06f VMware fix)</span></span>
<span class="line"><span>   0x8F000-0x94FFF   OCBL identity page tables (2 MiB huge pages, 4 GiB)</span></span>
<span class="line"><span>   0x98000  4 KiB    OCST state area      magic &quot;OCS1&quot; - kernel stage/</span></span>
<span class="line"><span>                      heartbeat, blind-written by OCOS, read by OCBL/OCIRE</span></span>
<span class="line"><span>   0x9B000  4 KiB    OCST reserved area   magic &quot;OCB1&quot; - post-mortem</span></span>
<span class="line"><span>                      boot record (BOOT_FAILED / USER_REQUEST)</span></span>
<span class="line"><span>   0x9FC00            EBDA (SeaBIOS)</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Payload placements:</span></span>
<span class="line"><span>   0x100000 (1 MiB)   OCOS kernel PT_LOADs (link base). OCSE too</span></span>
<span class="line"><span>                      (KERNEL_LMA 0x100000). Both images must stay</span></span>
<span class="line"><span>                      below 0x400000 (linker ASSERT in both scripts).</span></span>
<span class="line"><span>   0x400000-0x600000  the &quot;identity window&quot; - user address spaces remap</span></span>
<span class="line"><span>                      this virtual range to an empty PT, so the kernel</span></span>
<span class="line"><span>                      image may never grow into it (see memory.md)</span></span>
<span class="line"><span>   0x800000           mb2 &quot;self&quot; module: raw copy of the OCOS kernel ELF</span></span>
<span class="line"><span>                      (the installer payload pattern)</span></span>
<span class="line"><span>   0x01000000 (16 MiB) OCIRE link base (OCIRE_LMA) - disjoint from the</span></span>
<span class="line"><span>                      OCOS 1 MiB range so the supervisor&#39;s kexec of OCOS</span></span>
<span class="line"><span>                      into [0x100000, 0x800000) cannot overwrite itself</span></span></code></pre></div><p>Both monitor islands are carved out as <strong>E820 reserved</strong> in the mb2 memory map OCBL builds, so no OS ever allocates them; they were live-measured to survive QEMU warm resets (that is the whole point - a watchdog reset must not erase the evidence). The full story of these two blocks is <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>, the byte layout lives in <code>include/ocbl_state.h</code>.</p><h2 id="boot-modes" tabindex="-1">Boot modes <a class="header-anchor" href="#boot-modes" aria-label="Permalink to &quot;Boot modes&quot;">​</a></h2><p>OCBL supports eight distinct paths out of <code>ocbl_menu_run()</code>; the first five are the &quot;boot modes&quot; proper:</p><ol><li><strong>BIOS / El Torito (ISO)</strong> - the whole El Torito image is preloaded by SeaBIOS; stage1 at 0x7C00 finds the core already at 0x7E00, prints <code>OCBL stage1 ok</code>, enables A20 (int 15h AX=2401, then port 0x92, with two independent alias write-tests - both must fail before A20 is declared off), and jumps through its own GDT into 32-bit <code>core_head</code>.</li><li><strong>BIOS / MBR (installed disk)</strong> - the silent 512-byte stage1 variant. A patch block at image offset <code>+0x1A0</code> (<code>&#39;OCBL&#39;</code> magic, core LBA, sector count - written by <code>ocbl-install</code>) drives int 13h AH=42h reads of the core into 0x7E00. The retry loop deliberately never resets the drive: a reset clears SeaBIOS&#39;s PIO-fallback state and loops forever (live-caught WP06b b5). Bytes 446..509 stay zero in the image so the real partition table can be copied over them at install time.</li><li><strong>UEFI</strong> - <code>BOOTX64.EFI</code>, a PE/COFF app built by the in-tree <code>ocbl/elf_to_efi.py</code> converter (complete <code>.reloc</code> directory derived from <code>ld --emit-relocs</code>; the plain <code>ld -m i386pep</code> output emitted a partial directory and OVMF mis-relocated it). Same scanner, menu and handoff, with GOP/GetMemoryMap/ExitBootServices substitutions and a 64-&gt;32 downgrade blob at 0x30000.</li><li><strong>VBR chainload (BIOS)</strong> - foreign Windows/Linux/generic volumes: read the volume boot record, verify 0xAA55, copy to 0x7C00, drop to real mode and jump (the GRUB <code>chainloader +1</code> contract). An ESP that only carries <code>BOOTX64.EFI</code> is <strong>refused honestly</strong> (&quot;needs the UEFI flavor&quot;).</li><li><strong>UEFI chainload</strong> - <code>LoadImage</code>/<code>StartImage</code> of the foreign ESP loader, boot services kept alive, OVMF watchdog disarmed first.</li><li><strong>Shutdown</strong> - ACPI S5 through OCBL&#39;s own FADT/_S5 walk.</li><li><strong>Auto-recovery route</strong> - a pending BOOT_FAILED record makes OCBL boot the OCIRE entry one-shot, no menu interaction.</li><li><strong>A/B slot select</strong> - flag-file protocol on the first OCOS volume.</li></ol><h3 id="a-b-slots-and-automatic-rollback" tabindex="-1">A/B slots and automatic rollback <a class="header-anchor" href="#a-b-slots-and-automatic-rollback" aria-label="Permalink to &quot;A/B slots and automatic rollback&quot;">​</a></h3><p>The slot layout (<code>tools/make_ab_disk.sh</code>, documented in <a href="./ota-ab.html">ota-ab.md</a>): partition 1 = FAT32 flags volume carrying <code>/boot/next_B</code>, <code>/boot/bootfail_B</code>, <code>/boot/ok_B</code>; partition 2 = slot A; partition 3 = slot B. OCBL&#39;s <code>judge_volume()</code> implements the same semantics as <code>grub.cfg</code> and <code>grub-ab.cfg</code> (byte-identical flag contract in all three implementations):</p><ul><li><code>next_B</code> present AND <code>bootfail_B</code> absent -&gt; boot partition 3 (slot B);</li><li><code>next_B</code> AND <code>bootfail_B</code> both present -&gt; boot partition 2 (slot A), label suffix <code>&quot; rollback&quot;</code> - <strong>the automatic rollback</strong>: a slot-B kernel writes <code>bootfail_B</code> pessimistically at boot and removes it only when <code>ota_update_confirm_boot()</code> declares the system fully up, so a B kernel that dies mid-boot rolls the machine back to A on the next reset;</li><li><code>ok_B</code> present -&gt; slot B;</li><li>otherwise -&gt; slot A.</li></ul><p>The chosen slot&#39;s volume is re-mounted and the entry re-points at it; partitions 2/3 of that disk are &quot;slot-consumed&quot; and cannot register their own entries. A volume carrying both <code>/boot/opencube.elf</code> and <code>/boot/ocire.elf</code> exposes the OCIRE recovery entry too (WP06g3-4.4 - the scanner&#39;s short-circuit used to hide it).</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>The loader chain, scanner classes and handoff details: <a href="./boot-flow.html">boot-flow.md</a></li><li>What lives in every directory of the tree: <a href="./tree-map.html">tree-map.md</a></li><li>The cross-component mechanisms (state islands, watchdog relay, guard channel): <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a></li><li>The ring-3 API contract: <a href="./private-headers.html">private-headers.md</a></li><li>OCIRE in depth: <a href="./../dev/ocire.html">../dev/ocire.md</a>, and the user-facing side: <a href="./../manual/boot-modes.html">../manual/boot-modes.md</a>, <a href="./../manual/recovery.html">../manual/recovery.md</a></li></ul>`,26)])])}const u=a(t,[["render",i]]);export{m as __pageData,u as default};
